INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('catacomb-3-d', 8705, '1991-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gpe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3wqi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catacomb 3-D', 'Catacomb 3-D is the third in the Catacomb series of video games, and the first of these games to feature 3D computer graphics. The game was originally published by Softdisk under the Gamer''s Edge label, and is a first-person shooter with a dark fantasy setting. The player takes control of the high wizard Petton Everhail, descending into the catacomb of the Towne Cemetery to defeat the evil lich Nemesis and rescue his friend Grelminar.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 8705 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 8705 AND c.slug = 'softdisk-publishing' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 8705 AND c.slug = 'id-software' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 8705 AND p.igdb_id = 13 ON CONFLICT DO NOTHING;
