INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Munchers', 'Super Munchers is a trivia action game. The player moves their muncher around a grid and eats words that fit a given clue or category. Incorrect words and a variety of critters get in the way.' FROM games WHERE igdb_id = 50336 ON CONFLICT (game_id, language_code) DO NOTHING;
