INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolf Fang: Kuhga 2001', 'Wolf Fang: Kuuga 2001 was released in Japanese arcades in 1991. It was released in arcades outside Japan and re-titled Rohga: Armor Force. The arcade versions outside Japan however, have a number of things cut. There is no story intermissions between the stages and there is no stage selection leading to 4 different endings found on the Japanese version, but the game cycles through all 12 stages like in the Japanese version''s expert mode.' FROM games WHERE igdb_id = 377549 ON CONFLICT (game_id, language_code) DO NOTHING;
