INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arctic Adventure', 'Like Pharaoh''s Tomb, Arctic Adventure is a CGA game containing 80 all-new diabolical levels, packed with mind-bending arcade action designed to keep you from ever succeeding. Nevada will face freezing waters, diabolical traps, slippery ice patches, falling stalactites, runaway snowballs and even abominable snowmen! There are many, many more obstacles for Nevada to overcome in this highly adventurous series.' FROM games WHERE igdb_id = 8488 ON CONFLICT (game_id, language_code) DO NOTHING;
