INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baby Jo In ''''Going Home''''', 'Baby Jo in "Going Home" is a side-scrolling platform game. Jo can pick up rattles which can be tossed at enemies (such as bees, lawnmowers or spiders). Apart from watching out for the baby''s dropping health (represented as an increasingly tearful face), the baby''s diaper gets wetter over time and the thirst increases, too. If the diaper becomes too wet or the baby becomes too thirsty, the player immediately loses a life, so collecting fresh bottles and diapers is important.' FROM games WHERE igdb_id = 11930 ON CONFLICT (game_id, language_code) DO NOTHING;
