INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videomation', 'With Videomation, everyone is an artist! Videomation has drawing tools, stamps and an animation feature that lets your imagination go wild! Use with the NES to create vivid pictures with spectacular colors - some you can even program to move! Add fun stamps to your drawing and direct the animation selection to make it come alive. Hook up your VCR with Videomation to create wonderful, crazy additions to your family videos. It''s easy enough for everyone! Bring the action of a starship battle or the mystery of a dark forest into your home. Remember, the only limits to Videomation is your own imagination!' FROM games WHERE igdb_id = 18309 ON CONFLICT (game_id, language_code) DO NOTHING;
