INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('football-international', 49079, '1991-06-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hen.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv46a.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football International', 'Football International is a top-down soccer game with eight national teams to choose from. The player can either participate in an exhibition match or in a knockout championship. Other options which can be set is the time a half-time lasts and if the own team uses a more defensive or offensive lineup. The game itself consists of the usual dribbling, passing and shooting. Normally the camera closely follows the ball carrier, but when a wide shot is performed it zooms out and shows the whole playfield.' FROM games WHERE igdb_id = 49079 ON CONFLICT (game_id, language_code) DO NOTHING;
