INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hal Wrestling', 'Get a headlock on fun with Hal Wrestling! Eight rompin'', stompin'' brutes squares off in a head-to-head matches any sports fan can enjoy! All the pro wrestling moves you can use and a few you haven''t seen before! Go one-on-one against the computer or a friend, or round up your own four-man wrecking crew for thunderous action! Hal Wrestling - we''re coming to get YOU!' FROM games WHERE igdb_id = 48993 ON CONFLICT (game_id, language_code) DO NOTHING;
