INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'California Games', 'Introducing the gnarliest bunch of games under the sun! Games invented on the beaches by sun-baked beach bums with a fondness for ripping, grinding, and shredding. With six radically thrilling events intended to bring you to the edge and blow your mind. And make adrenaline California''s most plentiful natural resource.' FROM games WHERE igdb_id = 263875 ON CONFLICT (game_id, language_code) DO NOTHING;
