INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sid Meier''s Civilization', 'Sid Meier''s Civilization is a turn-based strategy computer game created by Sid Meier for MicroProse in 1991.The game''s objective is "...to build an empire that would stand the test of time". The game begins in 4000 BC, and the players attempt to expand and develop their empires through the ages until modern and near-future times. It is also known simply as Civilization.' FROM games WHERE igdb_id = 902 ON CONFLICT (game_id, language_code) DO NOTHING;
