INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sangokushi Retsuden: Ransei no Eiyuu-tachi', 'Sangokushi Retsuden: Ransei no Eiyuu-tachi is a 1991 simulation game by Sega released in Japan — and China, where it was called San Guo Zhi Lie Zhuan: Luan Shi Qun Ying. Whether or not the game has any connections to Koei, who makes the most popular games based around China''s Three Kingdoms time periods, is unknown.' FROM games WHERE igdb_id = 45610 ON CONFLICT (game_id, language_code) DO NOTHING;
