INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('le-tresor-dali-gator', 336174, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k36.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Le Trésor d''ali Gator', 'Legend tells of a pirate called Ali Gator whose treasure lies in a castle. You have gone to the castle to search for the treasure. It’s a simple exploration game where you wander around a maze of only 49 rooms, but there are many traps to catch you out. The game is quite a departure for Lankhor, who specialised in text adventures on the CPC – and they should have stuck to what they knew best. It’s written by Claude Le Moullec, who also wrote dozens of listings for French magazines, and in fact, it was originally intended to be a listing as well.' FROM games WHERE igdb_id = 336174 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 336174 AND c.slug = 'lankhor' ON CONFLICT DO NOTHING;
