INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HeroQuest', 'The famous fantasy-themed board game was converted into an isometric-viewed role playing game in which the evil Wizard Morcar must be defeated. You take control of a wizard, a dwarf, a barbarian and an elf, each with different strengths and weaknesses, who each start the 14 missions from opposite sides of the board.
