INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Medal City', 'Medal City is a card game for the Sega Mega Drive, released exclusively in Japan in 1991 via the Sega Game Toshokan service. You choose between three gambling games; Poker, Blackjack, and Slots. The goal of each game (besides poker) is to earn over 100,000 medals. You will then see the game''s ending (except poker, as the game never ends).' FROM games WHERE igdb_id = 45721 ON CONFLICT (game_id, language_code) DO NOTHING;
