INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario the Juggler', 'Mario the Juggler is a Game & Watch reworked version of 1980''s Ball, with Mario themes replacing the original''s generic juggler and his balls. It was the final Game & Watch ever released. The goal of the game is to keep juggling balls, bombs, stars, hearts, and other iconic Mario objects.' FROM games WHERE igdb_id = 131952 ON CONFLICT (game_id, language_code) DO NOTHING;
