INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wibbling-wilf', 73099, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8sm8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctufl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wibbling Wilf', 'Essentially a Pac-Man variant, the particulars of this top-down monster-avoiding maze-completing game do a good job at concealing its origins. You control Wilf (an homage to magazine editor Wilf Hey, in an unabashed bid for a good review), an innocent dumped by circumstances beyond his control into a maze inhabited by sinister Glumphs. Armed with nothing but a drippy jam sandwich, your goal is to travel around the entire game board dropping jam on the ground without being eaten by Glumphs. Take too long and they''ll unleash Frank the boiled sweet, who will undo your hard work by gobbling your tasty jam splatters.' FROM games WHERE igdb_id = 73099 ON CONFLICT (game_id, language_code) DO NOTHING;
