INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dottori-kun', 'This is a game that Sega used in-house to test the hardware it was developing during the late 1980s through the early 1990s. It is a simple game that lacks sound and the familiar player prompts (e.g. "insert coin"). It was never fully developed nor intended to be released to the public.' FROM games WHERE igdb_id = 40099 ON CONFLICT (game_id, language_code) DO NOTHING;
