INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ashita no Joe', 'The player stars as Joe Yabuki, an aspiring boxer, as he goes from an unknown kid from the rough side of town to a boxing champion. The game follows the traditional beat ''em up format, with some portions taking place inside a boxing ring and others taking place in the back alleyways, as Joe trains, fights bullies, and then fights in the boxing ring.' FROM games WHERE igdb_id = 39578 ON CONFLICT (game_id, language_code) DO NOTHING;
