INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Land', 'Dino Land is a dinosaur themed pinball machine. You basically have the shoot your pinball at dinosaur targets. As you go along, you get more points after you have hit all the dinosaur targets in the board. There are 4 pinball boards, one on ground with ground creatures, an air one that represents flying creatures, a sea level which has sea creatures, and a boss level where you are trying to save your girlfriend from the boss.' FROM games WHERE igdb_id = 4430 ON CONFLICT (game_id, language_code) DO NOTHING;
