INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Force', 'Tank Force is a multi-directional shooter arcade game that was released by Namco in 1991; it was the last game to run on their System 1 hardware (which had been in use for four years), is the sequel to Battle City, which was released six years earlier and is a sequel to Tank Battalion, which had been released five years before it (and eleven years before this title). The US version of the game was also the first of seven games from the company to display the Federal Bureau of Investigation''s "Winners Don''t Use Drugs" screen during its attract mode - the others are Steel Gunner 2, F/A, Cosmo Gang the Puzzle, Knuckle Heads, Lucky & Wild, and Numan Athletics. Exvania and Super World Court, which were Japan-exclusive, may also feature the screen in their attract mode if the "Display FBI Screen" setting in the games'' options menus has been set to "Yes".' FROM games WHERE igdb_id = 68378 ON CONFLICT (game_id, language_code) DO NOTHING;
