INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gobliiins', 1930, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ibj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvnb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gobliiins', 'Gobliiins is an adventure game where the player controls a team of three goblins: Oups, Ignatius and Asgard (Hooter, Dwayne, and BoBo in the US release) to find four magic components. A voodoo doll has turned their king Angoulafre mad and by collecting the components they can track down Niak the Wizard, the only one who can put things right. The player needs to solve various puzzles by combining the different skills of the three goblins. It''s possible switch between them and control them separately. Most of the puzzles are based on coordinated actions. One can cast powerful but erratic spells, another can collect and use objects, and the last can hit things. Action icons are activated at the bottom of the screen. The game takes in 22 landscapes, each of which has puzzles which must be cleared. The characters have limited energy, which can be sapped by traps.' FROM games WHERE igdb_id = 1930 ON CONFLICT (game_id, language_code) DO NOTHING;
