INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sunset Riders', 'Sunset Riders is a side-scrolling run and gun video game developed and released by Konami in 1991. It is set in the American Old West, where the players take control of bounty hunters who are seeking the rewards offered for various criminals. Each bad guy has a big reward on his head, and they''re helped by hordes of bandits, gunslingers, and horse thieves, so pack loads of lead.' FROM games WHERE igdb_id = 4370 ON CONFLICT (game_id, language_code) DO NOTHING;
