INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guldkornexpressen', 'Produced as a product tie-in with OTA''s honey puff cereal, Guldkornexpressen (or Kalaspuffsexpressen) revolves around the brand''s bear mascot, who drives a train filled with honey puffs. His task on each level is to pick up boxes of the cereal, add honey and drive the train to the end of the level, where the cargo is loaded into a big box of Guldkorn.
