INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pp-hammer-and-his-pneumatic-weapon', 12712, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vf2ngzl6j3qrooflxjsy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scovxf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'P.P. Hammer and His Pneumatic Weapon', 'P. P. Hammer and his Pneumatic Weapon is a platform game with puzzle elements. It draws obvious influence from the earlier game Lode Runner. In the game, you control a character called P. P. Hammer, who is on a quest to discover and acquire all treasures from a series of more than 60 levels. These levels are divided into four graphical themes: Ancient Rome, Ancient Egypt, Medieval castles, and ice. A fifth theme, LegoLand, appears on bonus levels. Each level in the game is made up of rectangular blocks, and contains various things including treasures, enemies, locked doors, bonus items and traps. P. P. Hammer carries a jackhammer, which allows him to drill through a block he''s standing next to. As in Lode Runner, drilling through more than one layer of blocks requires creating a triangle-shaped cavity more than one block wide, and blocks reappear after a short while. A block reappearing on top of P. P. Hammer kills him. P. P. Hammer can collect treasures and various power-up potions lying around the level. When he has collected all the treasures, the exit door opens, and going through the exit door completes the level. The player doesn''t have to play from the beginning of the game every time; after completing each level a level password is displayed, allowing the player to continue from that point at a later time.' FROM games WHERE igdb_id = 12712 ON CONFLICT (game_id, language_code) DO NOTHING;
