INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paperboy 2', 'You''re a paper boy (or papergirl). Get on your bicycle. Avoid obstacles on the road, such as dogs, cars, and basically everything you can imagine. Hell, some people shoot cannon balls at you! And you''d better be very sure to only throw papers at the right houses!' FROM games WHERE igdb_id = 12458 ON CONFLICT (game_id, language_code) DO NOTHING;
