INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NES Open Tournament Golf', 'NES Open Tournament Golf is an NES game featuring Mario characters. As the name of the game implies, it is a golf game and was one of the first golfing games in the Mario series. You can play a round of golf on one of three different courses. One or two players can play in the U.S., Japan, or the U.K. and choose a stroke or match play game. Gameplay is from two point of views, starting with an overhead view allowing you to set up the shot and choose a club, then switching to a 3-D point of view. Hitting the ball uses the common power meter where tapping the button starts the meter, tap the button a second time to select the amount of power in the shot, then tap the button a third time to select the amount of slice or hook.' FROM games WHERE igdb_id = 3400 ON CONFLICT (game_id, language_code) DO NOTHING;
