INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Ace II: Borf''s Revenge', 'Another Laserdisc conversion of one of Don Bluth’s cartoons: Space Ace II: Borf’s Revenge continues the saga of young cadet Dexter, who tries to free his love Kimberly from the clutches of the evil nemesis Borf. In critical situations, the meek Dexter can transform into his mighty alter ego Space Ace. Thus empowered, he has to defeat Borf’s minions.
