INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ka-Ge-Ki: Fists of Steel', 'Ka•Ge•Ki is a slightly-angled 3rd person beat-''em-up set around underground fighting matches a la Pit-Fighter in which you must take down every member of a notorious biker gang. Each match begins with a showdown with several weaker henchmen and then moves on to next of the 9 gang members, who must be KO''d 3 times before moving on to the next round. 
