INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D/Generation', 'Alone with your jetpack, you have flown from Finland across the Urals and the entire length of Asia to deliver a package to Genoq Biolabs in Singapore. You land on the building`s 80th floor setback, finding nobody there to greet you. When you enter the building, the main door snaps shut behind you, and you narrowly escape being killed by the building`s security system.
