INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ax Battler: A Legend of Golden Axe', 'Use your wits and your razor sharp sword to recapture the Golden Axe from the diabolical Death Adder. Defeat skeletons and giant bats in dark, deep chasms and caves. And summon Earth, Thunder and Fire Magic to fight gargoyles that come to life before your eyes!' FROM games WHERE igdb_id = 19485 ON CONFLICT (game_id, language_code) DO NOTHING;
