INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dangerous Dave in the Haunted Mansion', 'You''re a one-of-a-kind dangerous guy named Dave. Born and raised in the hill country of Backwater, USA, you''re quite deft with the shotgun, and afraid of nothing. Then again, you haven''t been in the haunted mansion up on the hill. As you hunt for your lost little brother, Delbert, you must enter a house full of zombies, spooks, and bad guys and turn them into hamburger meat, before they make a meal out of you in Dangerous Dave in the Haunted Mansion!' FROM games WHERE igdb_id = 11386 ON CONFLICT (game_id, language_code) DO NOTHING;
