INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tricky Kick', 'Flex your thumbs and tease your brain! TRICKY KICK takes brain teasing puzzle gaming into the next dimension. Six different Heroes, trapped in a mixed-up, matched-up world of obstacles, baffle their way through hostile hazards. Weave your way through 120 levels of mind-bending possibilities where wild animals, robots, spooks, and trolls try to keep you from your goal. Designed for puzzlers of all ages, TRICKY KICK will quickly become a game you''ll find hard to quit.' FROM games WHERE igdb_id = 92879 ON CONFLICT (game_id, language_code) DO NOTHING;
