INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gunforce', 'GunForce: Battle Fire Engulfed Terror Island or simply titled as GunForce, is a side-scrolling action shooting game produced by Irem for the arcades in 1991. The game was later ported by Bits Studios and published by Irem to the Super Famicom exclusively in Japan in 1992.
