INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rent-A-Hero', 'Rent A Hero is an action role-playing video game series released by Sega for the Mega Drive console in 1991 with a large emphasis on humor. The game features the same graphic engine previously used in the development of Sword of Vermilion. However, Rent A Hero has an unusual innovation for the genre. Instead of using standard turn-based battles, fights are in a similar format to 2D fighting games.' FROM games WHERE igdb_id = 145509 ON CONFLICT (game_id, language_code) DO NOTHING;
