INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spacewrecked: 14 Billion Light Years From Earth', 'In this sci-fi RPG you are sent to a fleet of spaceships which have been invaded by aliens who escaped during a routine mission. This involves walking around and fighting off any aliens you encounter, while collecting keys for the doors. A toxic coolant must be handled carefully if this is to be achieved. 6 programmable robots can help with repair chores The game''s control system has a direction pad for moving and inventory mapping.' FROM games WHERE igdb_id = 50264 ON CONFLICT (game_id, language_code) DO NOTHING;
