INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario World: Mario to Yoshi no Bouken Land', 'Super Mario World: Mario to Yoshi no Bouken Land, is a 28-minute interactive anime video based on the game Super Mario World published by Bandai in 1991. It is designed for use with Bandai''s Terebikko system, which utilizes a telephone-shaped microphone to "interact" with the video. It asks the viewer multiple choice questions, and prompts the user to answer by pressing one of four numbered buttons. Although made for use with the Terebikko system, the video can also be played on an ordinary VHS player.' FROM games WHERE igdb_id = 230281 ON CONFLICT (game_id, language_code) DO NOTHING;
