INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander Keen: Goodbye Galaxy!', 'Following the Invasion of the Vorticons, the story arc of Goodbye Galaxy! takes Commander Keen to a planet to rescue the Keepers of the Secret of the Oracle, which know the location of the Shikadi''s doomsday device, The Armageddon Machine.' FROM games WHERE igdb_id = 143831 ON CONFLICT (game_id, language_code) DO NOTHING;
