INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Commander Keen in Keen Dreams', 'Trapped in a land where giant vegetables rule the day, you must fight your way through an army of vicious broccoli beasts, savage asparagus warriors and a bushel of other leafy green nasties before battling the fiercest spud of all, King Boobus Tuber. Unless you want a one way trip to the salad bar in the sky, you''ll have to finish all your veggies. Before they finish you!' FROM games WHERE igdb_id = 2442 ON CONFLICT (game_id, language_code) DO NOTHING;
