INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heart of China', 'Kate, the daughter of a wealthy businessman named E.A. Lomax, is abducted by a Chinese warlord named Li Deng near Chengdu, where she was volunteering as a nurse. Lomax recruits the former World War I fighter pilot Jake "Lucky" Masters for a dangerous mission: travel to Hong-Kong, locate a mysterious ninja, and find a way to infiltrate Li Deng''s fortress and rescue Kate.
