INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heartlight', 'Heartlight is a puzzle video game originally developed by Janusz Pelc for the Atari 8-bit computers in 1990. In 1994, an MS-DOS port (Heartlight PC) was published by Epic MegaGames along with two other games by Janusz Pelc in the Epic Puzzle Pack. The shareware version has 20 levels and the full version (Heartlight Deluxe) has 70 levels. In 2006, Maciej Miąsik, co-author of the MS-DOS version, released it under the Creative Commons CC BY-SA 2.5 license as freeware. The source code became available too. In 2020, a web browser remake was released with updated graphics.' FROM games WHERE igdb_id = 57585 ON CONFLICT (game_id, language_code) DO NOTHING;
