INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('knights-of-the-round', 6816, '1991-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7k33.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nrf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knights of the Round', 'The gameplay is very similar to other Capcom beat ''em ups, such as Final Fight and Capcom''s previous hack-and-slash fantasy title The King of Dragons. There are seven stages, each with its own boss and a variety of generic enemies that try to stop the players'' progress. The fights rely strongly on blocking ability, which is triggered by pressing the attack button, then pressing the joystick away as the opponent strikes. If successful, the player gains a few seconds of invincibility with which to counter-attack. However, if no one strikes the player''s character while holding the block, they will tire and drop their guard, making them vulnerable to attack. Blocking is vital in certain cases, since some bosses will be vulnerable only after their attack has been blocked by the player.
