INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lemmings', 'Lemmings is a puzzle-platform game developed by DMA Design and published by Psygnosis in 1991. Players guide a group of lemmings through hazardous levels to a designated exit. The gameplay involves assigning specific skills, such as digging or building, to overcome obstacles and avoid traps. Each level has a time limit and requires saving a minimum number of lemmings to progress. The game was released on multiple platforms and is regarded as a classic of the puzzle genre.' FROM games WHERE igdb_id = 4239 ON CONFLICT (game_id, language_code) DO NOTHING;
