INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Don''t Pull', 'A puzzle game similar to games like the Adventures of Lolo series, Pengo, and Capcom''s own puzzle game Pirate Ship Higemaru. It involves the player controlling either a rabbit named Don (Player 1) or a squirrel called Pull (Player 2), pushing blocks to crush monsters. Unlike the other two games, it is neither connected to both and there is no plot or backstory behind the game’s events.' FROM games WHERE igdb_id = 361332 ON CONFLICT (game_id, language_code) DO NOTHING;
