INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Max', 'Metal Max is a 1991 vehicle combat role-playing video game developed by Crea-Tech and published by Data East for the Nintendo Famicom exclusively in Japan on May 24, 1991 and later re-released on the Wii Virtual Console on April 27, 2010. It is the first of the Metal Max series. Metal Max is set in a futuristic post-apocalyptic world, where the surviving humans cluster in underground villages and ruins while "monster hunters" fight the monsters and outlaws outside.' FROM games WHERE igdb_id = 48428 ON CONFLICT (game_id, language_code) DO NOTHING;
