INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Crusaders', 'They struck without warning, wiping out the Earth''s defenses in one master stroke. Cities were crushed, and the invading aliens showed no mercy! A small resistance force of Ninja, refusing to be conquered, still remained to fight the evil Inimicus. A daring plan was devised by the Ancient Ones to send out two special Ninja, and annihilate the alien threat once and for all!' FROM games WHERE igdb_id = 48193 ON CONFLICT (game_id, language_code) DO NOTHING;
