INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spirit of Adventure', 'In a medieval fantasy world, strange drugs appear that create an addiction among the population. It appears that they are all coming from one central point that is controlled by a mysterious stranger. The player controls a group of heroes in this role-playing game as he tries to find out the origins of the drug and to break down on the man who is responsible for them.
