INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-fighter', 14662, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rxg2vgk39l8fanm9wpjz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ej6ex3w6e0uahbdjbqrc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Fighter', 'The player takes control of a magical human fighter who has the ability to transform himself into a flying dragon. As the fighter, the player can run, crouch, jump, and attack with his sword as he would in most side-scrolling action games. Underneath his life gauge is a "metamorphosis gauge" that will gradually be filled as the player destroys his enemies. When the metamorphosis gauge begins to flash, the player can transform into the dragon by pressing up and A button after jumping. As a dragon, the player will hover in the air while the screen scrolls automatically to the right, similarly to a side-scrolling shoot-''em-up game. The dragon''s main attack is his fire breath. While the player can fly in any of the eight directions, they cannot turn around and the dragon will only face and attack to the right. While in dragon, the player''s metamorphosis gauge will gradually be drained out. The player will transform back to a fighter if the metamorphosis gauge empties out completely or when the player rapidly taps the A button again. 
