INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xyphoes Fantasy', 'In the land of Norem, an army of warriors called the Skulls have caused a magician to lose all of his powers. He has chosen you to trek across Norem and clear it of the Skulls and their evil leader, Kan. There are four levels: a mixture of shoot ''em-up action, and one-on-one sword fighting against two of Kan''s finest warriors.' FROM games WHERE igdb_id = 10854 ON CONFLICT (game_id, language_code) DO NOTHING;
