INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lord Monarch', 'Lord Monarch is a real-time strategy war game by Nihon Falcom. The game is considered to be the seventh installment in the Dragon Slayer series. It was originally released in 1991 for the NEC PC-9801, and was later ported with enhanced theme swapping in 1992 to the Super Famicom, and then in 1994 to the Sega Mega Drive as "Lord Monarch: Tokoton Sentou Densetsu". During 1997, Lord Monarch was remade for Windows as "Lord Monarch Online" and released for free in both Japanese, and for the first time, English.' FROM games WHERE igdb_id = 37941 ON CONFLICT (game_id, language_code) DO NOTHING;
