INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rail Chase', 'Rail Chase is a Sega Y Board arcade light gun game developed by Sega AM3 and published by Sega. Released in Japan in September 1991, and in the United States later that year, the game came in both standard and DX cabinets (the latter seats players in the pneumatic "Magical Bench Seat", which tilts and rocks with the in-game action), and uses sprite scaling to simulate three-dimensional scenery.
