INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Ghouls''n Ghosts', 'As dauntless knight Arthur you are caught up in the most dangerous of quests! A spell has been cast upon the kingdom. Your fair maiden, Princess Prin Prin has been snatched up by the evil emperor. Only as Arthur can you get her back from the creatures of the undead that haunt the land. Test your courage and skill to the limit. You must keep up the quest. On your journey, your mightiest weapon of all awaits you... MAGIC!' FROM games WHERE igdb_id = 6621 ON CONFLICT (game_id, language_code) DO NOTHING;
