INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad TV', 'Mad TV is a television station management simulation computer game produced in 1991 by Rainbow Arts. It is loosely based on Mad Magazine, and the game''s introduction animation features the magazine''s mascot, Alfred E. Neuman, smiling on a television. The game puts the player in the role of a new program director for a TV station. The player is in charge of selecting programming and earning advertising for the station, while simultaneously trying to marry Betty, an attractive woman working in the building.' FROM games WHERE igdb_id = 14719 ON CONFLICT (game_id, language_code) DO NOTHING;
