INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zone Warrior', 'Zone Warrior is a side-scrolling platform game with exploration and shooting elements. It consists of five levels: Prehistoric, Egyptian, Medieval, Japanese and Future zones. Various enemies stand in the way, fitting the respective time period: dinosaurs and cavemen in prehistoric times, pharaohs in Egypt, robots in the future.' FROM games WHERE igdb_id = 130079 ON CONFLICT (game_id, language_code) DO NOTHING;
