INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burai Fighter Deluxe', 'The player starts out with a relatively weak cannon but can upgrade to ring, laser, and missile weapons, which are much more powerful. The player can also choose from three difficulty settings: Eagle, Albatross, and Ace; but the fourth difficulty setting, Ultimate, must be unlocked. One proceeds by controlling the character in 8 directions and can shoot in a different direction from the direction he is looking.' FROM games WHERE igdb_id = 48960 ON CONFLICT (game_id, language_code) DO NOTHING;
