INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('high-speed', 48156, '1991-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o04.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Speed', 'The hottest pinball game ever has been converted to video! All the action and excitement of the original HIGH SPEED is here - Freeway Frenzy, Ramp Race and Running the Red - plus excellent new features like Lightning Bombs and attacking enemies! It''s a real-life adventure. The screen flashes and a siren shrieks when you run the red light! Police car radio messages and original chase music both add to the thrills. Go for the burn - grab the jackpot and get away at HIGH SPEED!' FROM games WHERE igdb_id = 48156 ON CONFLICT (game_id, language_code) DO NOTHING;
