INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clystron', 'In Clystron you control a walker-like cyborg on its mission to find eight machine parts. The parts must be collected in the correct order. Whenever a part is found, a new transporter destination is unlocked. All parts must be found within a time limit of 15 minutes in order to complete the game.
