INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'P-38 Lightning Tour of Duty', 'An expansion to Secret Weapons of the Luftwaffe that allows players to fly in, and against, the unique P-38 Lightning. Players assume the role of a P-38 pilot, engaging in a series of historically-inspired missions that showcase the aircraft''s diverse capabilities. These likely range from high-altitude interceptions and long-range escort missions to ground attack sorties, reflecting the P-38''s real-world adaptability. The game probably features multiple campaign settings, potentially including the Mediterranean, Pacific, and European theaters, where the P-38 saw extensive action. With its emphasis on historical accuracy, P-38 Lightning Tour of Duty offers aviation enthusiasts and World War II buffs an immersive experience that combines realistic flight simulation with the strategic and tactical challenges faced by Allied pilots during the war.' FROM games WHERE igdb_id = 197 ON CONFLICT (game_id, language_code) DO NOTHING;
