INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-king-of-dragons--1', 6814, '1991-08-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y8f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ajhbyacf5lmzc42akiou.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Dragons', 'The game has 16 levels, though many are quite short. Much like Capcom''s Knights of the Round, King of Dragons features an role-playing video game-like level advancement system. Points scored for killing monsters and picking up gold count towards experience, and the character gains levels at regular intervals. With each level, the character''s health bar increases, other attributes such as range improve, and the character also becomes invulnerable for a few seconds. Along the way, different weapon and armor upgrades for each character may also be picked up.
