INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block Shock: The Last Chance', 'Block Shock: The Last Chance is a tile-based puzzle/arcade game. Players control a helicopter dodging descending blocks while trying to complete full rectangles or squares. When successful, those blocks disappear—but new ones scroll in from above. The game ends if any block reaches the bottom of the screen before being cleared. It features steadily increasing difficulty and delivers fast, continuous gameplay' FROM games WHERE igdb_id = 14321 ON CONFLICT (game_id, language_code) DO NOTHING;
