INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World League Soccer', 'Viewed top-down, the controls involve trapping the ball under your foot, giving you time to prepare passes. Running with the ball is tricky at first, as it doesn''t stick to your foot the way it did in contemporary football games. Complex moves such as overhead kicks, back-heels and long-range through-ball passes can be completed with practice.' FROM games WHERE igdb_id = 37249 ON CONFLICT (game_id, language_code) DO NOTHING;
