INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Hello', 'Dr. Hello is an unlicensed Dr. Mario clone developed for the MSX and ported to the Sega Master System. It was developed in South Korea by a company known as "Sis Co." in 1991, without the backing from either Sega or Nintendo. The game uses a completely different set of graphics and music to Dr. Mario, but the gameplay is exactly the same.
