INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Fighter', 'Returning from three centuries of intergalactic missions, MCS-920 is surprised by an alien-infested planet. Whatever few lifeforms survived were driven underground or transformed into battling bionic mutants. You must escape the tentacles of these mutants, seek out and destroy alien ships, then overpower grotesque alien guards to steal their fiendish and bizarre weapons. From barren landscapes and colorful coral reefs to abandoned and frozen cities, you will yet come face to face with the alien tyrant in each world!' FROM games WHERE igdb_id = 48171 ON CONFLICT (game_id, language_code) DO NOTHING;
