INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tournament-cyberball', 73029, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3z46.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sce6dp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tournament Cyberball', 'Tournament Cyberball is the sequel to Cyberball. The Cyberball series is a sci-fi imagining of American Football featuring giant robots as players, and a ticking time bomb as the ball. Players run plays, in the usual configurations familiar to American football games (pass plays, run plays, and options plays), in order to progress downfield and score touchdowns. Instead of downs and conversions in the usual sense, each time a team runs a play without passing the yardage necessary to achieve a first down, the ball gets hotter, eventually becoming critical. If the team with a critical ball fails to score or achieve a first down, the ball explodes, and any robot player holding the ball at the time is destroyed as well. The game does not feature field goals.
