INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cutie Suzuki no Ringside Angel', 'Cutie Suzuki no Ringside Angel (キューティー鈴木の リングサイドエンジェル) or Cuty Suzuki no Ringside Angel is a wrestling game developed by Copya System and published exclusively in Japan in 1990 by Asmik. In the game, you play as one of nine female Japanese pro wrestlers fighting to the top of the league. There are four modes: one-player tournament, two-player tournament, two-player match, or watch the computers play with the characters/field of your choice. There are five fields (New Face, Straw Berry, White Snow, Star Light, and Grand Champion). Each field is one half of a normal wrestling ring that the competitors can move around a la Golden Axe' FROM games WHERE igdb_id = 45732 ON CONFLICT (game_id, language_code) DO NOTHING;
