INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcus Odyssey', 'This is a Gauntlet-like game: lots of action and magic, with items to collects, and many dungeons to free from monsters. The game is also viewed from an isometric perspective, typical for the genre. Choose one of four characters to battle your way through dungeons and castles, or play with a friend in a 2-player mode' FROM games WHERE igdb_id = 16138 ON CONFLICT (game_id, language_code) DO NOTHING;
