INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splash Lake', 'Splash Lake is an action-puzzle game for the TurboGrafx-CD and PC Engine CD-ROM. The player is an ostrich named Ozzie and must walk around a grid, pecking at certain lynchpin areas of the ground in order to collapse parts of the level into the ocean. The goal is to remove all enemies by dropping the ground they''re walking on. It is structurally similar to Dig Dug 2.
