INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rim Rockin'' Basketball', 'This four-player game approaches basketball with a more serious attitude than some of the more well-known modern basketball games. Control one of five players on your team: Dribble, pass, shoot into the basket for score! Now repeat.' FROM games WHERE igdb_id = 40423 ON CONFLICT (game_id, language_code) DO NOTHING;
