INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Truck Rally', 'You''ve never experienced anything like the incredible action of MONSTER TRUCK RALLY! Compete against the computer - or against up to three of your friends at once - in nine grueling, gear-grinding events: hill climb, drag race, car crush, sled pull, monster rally, drawbridge, donuts, tug-o-war, and bog! Whether you build your own custom course, or have the computer build one for you randomly - out of millions of possible combinations - every event is sure to be an awesome new challenge, every time!' FROM games WHERE igdb_id = 48199 ON CONFLICT (game_id, language_code) DO NOTHING;
