INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gulf Storm', 'A politically somewhat explosive theme at the time, the player in Gulf Storm assumes the role of a military officer on the hunt for the worst Saddam Hussein double ever. On that mission, he doesn''t settle with a simple plane, but switches between a speedboat, a helicopter and a motorcycle, all the while wondering where the Iraqi found all those biplanes in 1991.' FROM games WHERE igdb_id = 40154 ON CONFLICT (game_id, language_code) DO NOTHING;
