INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Champions Forever Boxing', 'It''s Ali, Foreman, Frazier, Holmes and Norton -- five of the world''s greatest heavyweight boxing champs! Be them or battle them. Each has his actual physical traits and boxing style. Move and jab, or go toe-to-toe and unleash a flurry of punishing hooks, uppercuts and body shots. Protect yourself by blocking punches or clinching. Taunt opponents with showboat moves if you''ve got the guts. Fight exhibition matches or an entire 15-year career. Between round close-ups show each boxer''s facial damage. Beat these five legends and become a Champion Forever!' FROM games WHERE igdb_id = 42115 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42115 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
