INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WordZap', 'WordZap is a puzzle video game designed by Michael Crick included with Volume 3 of the Microsoft Entertainment Pack. In WordZap, players race to make proper English words to fill their rack of words, but when one player makes a word already found by the other player, the word is "zapped" from both players'' racks. Each round ends when either one player fills the word rack, or time runs out without either player being able to make another word.' FROM games WHERE igdb_id = 117962 ON CONFLICT (game_id, language_code) DO NOTHING;
