INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Klotski', 'Klotski is an ancient Polish game that provides mathematical problems in the form of a small wooden game board with various sized blocks. The object of the computer game is to free the "master block," in as few moves as possible. The computer scores you on the number of moves it takes to solve a puzzle. 24 puzzles are included, as well as a puzzle editor.' FROM games WHERE igdb_id = 282402 ON CONFLICT (game_id, language_code) DO NOTHING;
