INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rad Racket: Deluxe Tennis II', 'Six of the best international players have gathered to compete for a fortune in cash, plus the prestige that comes with winning the RAD RACKET trophy. The competition is fierce. You''ve fought long and hard to get this far. You''re gonna have to keep on winning tomake it to the top. Play singles or team up with a friend and play doubles. Either way you will experience the thrill of victory or the agony of defeat as you face off in a test for the best.' FROM games WHERE igdb_id = 48212 ON CONFLICT (game_id, language_code) DO NOTHING;
