INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Birds of Prey', 'Birds of Prey is a combat flight simulator set in a fictitious present-day world during a conflict between Soviet and Nato forces. The player can choose several different mission types to participate in the conflict and contribute in different ways. A wide variety of aircraft and arming options are available to choose from on both sides; the player decides for which side they will play at the start of the game.' FROM games WHERE igdb_id = 11962 ON CONFLICT (game_id, language_code) DO NOTHING;
