INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secret Scout in the Temple of Demise', 'Separated from your troops by unexplainable events, you are tring to find your way back to civilization. Just when you think you are going to be saved, the rescuing team turned out to be part of Dr. Demise''s organization. In order to sever his hold on the jungle region, you must search the ruins of an ancient temple in the hope of finding and destroying Dr. Demise.' FROM games WHERE igdb_id = 48200 ON CONFLICT (game_id, language_code) DO NOTHING;
