INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xak Precious Package: The Tower of Gazzel', 'Xak Precious Package: The Tower of Gazzel is a fantasy role-playing video game developed and published by the Japanese software developer MicroCabin. The game is a direct sequel to Xak: The Art of Visual Stage and Xak II: The Rising of the Red Moon. While technically being the third installment of the series, The Tower of Gazzel is a side story taking place between the events of Xak II and Xak III.' FROM games WHERE igdb_id = 41775 ON CONFLICT (game_id, language_code) DO NOTHING;
