INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ABC Wide World of Sports Boxing', 'ABC Wide World Of Sports Boxing is a boxing computer game released in 1991. The game allows for more than just boxing, letting the player create and then train and manage their own character. It is based on the American Broadcasting Company (ABC) program Wide World of Sports and was released at the time of the program''s 30th anniversary. Sportscaster Dan Dierdorf, then a boxing commentator for ABC, is featured in this game.
