INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakushou!! Jinsei Gekijoh 3', 'Bakushou!! Jinsei Gekijoh 3 ("Burst of Laughter!! Theater of Life 3") is a virtual life board game developed and published for the Nintendo Entertainment System by Taito on December 20th, 1991 in Japan. It is the third installment in the Bakushou!! Jinsei Gekijou series and follows in the same tradition by allowing up to four players to take part and travel around a virtual board through chance rolls, playing out a virtual life in its entirety from childhood to senior citizenship making important decisions along the way.' FROM games WHERE igdb_id = 48726 ON CONFLICT (game_id, language_code) DO NOTHING;
