INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle of Dr. Brain', 'Castle of Dr. Brain is the first in a two-part series of educational puzzle-games from Sierra. This brain-blasting game is set, how surprisingly, in Dr. Brain''s castle, where the player will have to beat Dr. Brain''s traps and puzzles in order to fulfill the assignment given.' FROM games WHERE igdb_id = 7722 ON CONFLICT (game_id, language_code) DO NOTHING;
