INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hovertank 3D', 'One of the first games of iD Software. Sometimes it''s claimed to be the first FPS or even first 3D game for DOS. The game used the same combination of scaled sprites and drawn walls that would later show up in Catacomb 3D and Wolfenstein 3D, but the walls in it are solid colors with no textures.' FROM games WHERE igdb_id = 18994 ON CONFLICT (game_id, language_code) DO NOTHING;
