INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpin'' Kid: Jack to Mame no Ki Monogatari', 'The evil Giant has kidnapped Jack''s girlfriend and now he must travel up the beanstalk and return to the Giant''s castle in the sky to save her! Jack must use all his jumping ability and wits to climb the dangerous beanstalk without getting hurt. Many wildlife creatures and the minions of the Giant stand in his way.' FROM games WHERE igdb_id = 48450 ON CONFLICT (game_id, language_code) DO NOTHING;
