INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Airwolf', 'Super Airwolf is a 1991 shoot-''em-up for the Sega Mega Drive by A.I and Kyugo to tie into Universal Pictures''s Airwolf television series and as a sequel to their 1987 arcade game Airwolf. However in the United States, they dropped the license and published the game as Cross Fire for reasons unknown.' FROM games WHERE igdb_id = 45548 ON CONFLICT (game_id, language_code) DO NOTHING;
