INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cal II', 'You are Wataru Ishibashi, a high-school student in modern Japan. Up until recently you led a normal life, enjoying the relationship with your lovely girlfriend Mika. But short before the graduation ceremony, you had a strange vision that you first believe to be a dream. But when you are contacted by Venus, the goddess of love, you realise Mika was abducted by Aeon, the goddess of time, and transferred into the Realm of Time. You must now travel to the legendary dream world of beautiful goddesses and bring Mika back.' FROM games WHERE igdb_id = 77989 ON CONFLICT (game_id, language_code) DO NOTHING;
