INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyatto Ninden Teyandee', 'Players take the role of the three main cats and otasuke (rescue team) members, who can be switched to at any time and have special abilities to progress through the game. The game features most of the characters in the series as well as an additional villain, a mysterious scientist named Dr. Purple (Dr. パープ).' FROM games WHERE igdb_id = 24480 ON CONFLICT (game_id, language_code) DO NOTHING;
