INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fighting Masters', 'A Giant Red Sun will go Nova within hours... 12 Star systems will be destroyed... One contest will decide who, or what, survives... Climb into the interstellar ring! Go One-on-One with another player, or battle for the survival of your civilization! 12 different Alien champions to select! From the snapping, tearing claws of Zygrunt to the bludgeoning ecto-clubs of Rotundo, each warrior has a deadly force all their own!' FROM games WHERE igdb_id = 46215 ON CONFLICT (game_id, language_code) DO NOTHING;
