INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gorby no Pipeline Daisakusen', 'In this falling-block puzzle game, a small girl—wearing a Russian national costume of sarafan, kokoshnik, and valenki—pushes tiles representing segments of water pipe down a two-dimensional, vertical shaft; this shaft is the field of play. A second girl, also in national costume, waves semaphore flags to give the impression that she guides the placement of the tiles.
