INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sel Feena', 'At a time when people were being terrorized by monsters, Selfeena, a little witch, wizard, and magic creature and her little dragon Rich Rich embarked on an adventure to reclaim the treasure stolen from the people by the monsters. Their weapon was the power to put the monsters in boxes. How much treasure can Selfeena recover?' FROM games WHERE igdb_id = 38602 ON CONFLICT (game_id, language_code) DO NOTHING;
