INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gulf War II', 'Gulf War-II is vertically scrolling shoot-em up, based on Twin Cobra code. The action takes place in the Persian Gulf - the place where the war continues. Gameplay is very typical: the player controls a plane, flies forward and shoots to enemies. He can gather power-up, to increase shoot power. Player''s plane has 2 weapons - gun with unlimited ammo and some very destructive bombs.' FROM games WHERE igdb_id = 40317 ON CONFLICT (game_id, language_code) DO NOTHING;
