INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tetrastar-the-fighter', 48387, '1991-05-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob5ik.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc1121k.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetrastar: The Fighter', 'Tetrastar The Fighter is a 3D shooter by Home Data and published by Taito. In the year 2089, humanity forms an alliance with the intergalactic Baal empire but soon Earth finds out about the alien''s true intentions. A group of resistance assembles the project Tetrastar to prepare for the potential upcoming threat. But the project lead by the general Nelson is soon put on hold and a short lived peace settles in. But the whole thing was nothing more than a hostile invasion and the Baal empire finally breaks the alliance and attacks Earth. The player''s first mission is to prevent New York to be destroyed and then to retrieve Omega, the faithful robot navigator, to warp to the alien''s mother world. The Tetrastar super fighter can move around the screen and fire a standard Vulcan gun. Special weapons become available later in the game from Bombs (WID), Homing Missiles (AAM), Napalm Bombs (NAP) and the powerful Bio Cannon (BIO) - they are accessible via the Select button and triggered by pressing A. They all come in limited quantities and must be refilled by picking up power-pods along the way. Tetrastar features nice stages and cutscenes between them unfold the game''s episodic story.' FROM games WHERE igdb_id = 48387 ON CONFLICT (game_id, language_code) DO NOTHING;
