INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('inindo-way-of-the-ninja', 47498, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2x8i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8znf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inindo: Way of the Ninja', '"Inindo: Way of the Ninja" is a console-style RPG with a touch of strategy. You navigate your hero on the world map, visit towns, and descend into dungeons. The battles are turn-based and are viewed from a third-person perspective, like in Final Fantasy games. You can move on the battle field and use melee or long-ranged attacks. You''ll be able to recruit characters of various classes to your party, who will join you for profit or for other reasons. After you gain enough experience, you''ll also be able to talk to daimyos (feudal rulers) of various castles and to convince them to work together against Nobunaga. You can also perform various tasks for the daimyos, such as spying.
