INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Captain Commando', 'Captain Commando is a futuristic side-scrolling beat ''em up video game. The game stars the titular superhero who was originally conceived as a fictional spokesman used by Capcom USA in the company''s console games during the late 1980s. Among its unique features are the option for 4 simultaneous co-op play and the ability to control mecha suits scattered on the stages.' FROM games WHERE igdb_id = 19821 ON CONFLICT (game_id, language_code) DO NOTHING;
