INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Neptune', 'Operation Neptune is an educational computer game produced in 1991 by The Learning Company. The goal of the game is to guide a small submarine through a variety of undersea caverns, collecting pieces of a ruined space capsule. Like other games by The Learning Company, Operation Neptune is educational and was intended for players age nine to fourteen (grades five through nine). It was released as part of the Super Solvers series for a time' FROM games WHERE igdb_id = 7472 ON CONFLICT (game_id, language_code) DO NOTHING;
