INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Down Load 2', 'In this sequel to Down Load, the player once again takes control of Syd, a young "cyber diver" - a highly trained agent who is able to infiltrate the "cyber world", a virtual reality network that has replaced real life for so many humans in this grim futuristic scenario of the end of the 21st century. This time, Syd is up against an even bigger menace: a terrorist organization that has taken possession of Adolf Hitler''s brain, in order to re-create it in a digital form, thus reviving one of the most vile and insane dictators in human history!' FROM games WHERE igdb_id = 85810 ON CONFLICT (game_id, language_code) DO NOTHING;
