INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pop Breaker', 'Pop Breaker is a puzzle shooter game for the Sega Game Gear. It was only released in Japan. Piloting a hovertank named Diana, Yuki Takeshita is a high school student who is taking the entry exam for FSWAT - a newly formed defense force. There are 50 levels that the player must complete, controlling Yuki''s hovercraft from an overhead perspective and navigating through a board-like environment.' FROM games WHERE igdb_id = 45251 ON CONFLICT (game_id, language_code) DO NOTHING;
