INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('navy-seals', 15268, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/r0n2jyuhkwgv72sumb7c.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Navy Seals', 'Navy SEALS is a shoot ''em up platform video game developed and published by Ocean Software. It was first released in the United Kingdom for the Amstrad CPC, Amstrad GX4000 and Commodore 64 in 1990. It was later re-released in the rest of Europe for the ZX Spectrum, Atari ST and Amiga home computers in the following year. It was then ported to the Game Boy on 1 September 1991 in the United States. The game is based on the film of the same name and follows the protagonist, Lieutenant Dale Hawkins, progressing through five side-scrolling levels.
