INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darius Twin', 'Darius Twin is a shoot ''em up video game released for the Super NES in 1991. It was the first new installment in the Darius series to not be originally designed for the arcades, and also the first to have a normal 4:3 screen-ratio. Interestingly, while it''s a unique game in the Darius series, it appears to reuse sprites and background designs from Darius and Darius II. Also, while the names of the bosses are new, they really are reworkings of previous bosses for the most part.' FROM games WHERE igdb_id = 6660 ON CONFLICT (game_id, language_code) DO NOTHING;
